#' Results Processing Functions
#'
#' Functions for post-processing simulation results including
#' efficiency calculations, minimum sample size determination, and plotting.

#' Calculate efficiency metrics relative to maximum sample size
#'
#' @param results Main results object
#' @param threshold Efficiency threshold
#' @return Updated results with efficiency metrics
#' @noRd
calculate_efficiency_metrics <- function(results, threshold) {
  validate_threshold(threshold)
  for (model in names(results)) {
    for (metric in names(results[[model]])) {
      metric_data <- results[[model]][[metric]]
      metric_data <- metric_data[order(metric_data$sample_size), , drop = FALSE]
      results[[model]][[metric]] <- metric_data
      perf <- metric_data$mean

      # Skip if all NA
      if (all(is.na(perf)) || !is.finite(perf[1]) || !is.finite(perf[length(perf)])) {
        results[[model]][[metric]]$efficiency <- rep(NA_real_, length(perf))
        next
      }

      max_perf <- perf[length(perf)]  # Performance at largest n
      min_perf <- perf[1]  # Performance at smallest n

      # Efficiency calculation depends on metric direction
      if (metric %in% c("mse", "rmse", "mae", "brier")) {
        # Lower is better - calculate improvement ratio
        # Efficiency = (initial_error - current_error) / (initial_error - final_error)
        if (min_perf == max_perf) {
          efficiency <- rep(1, length(perf))
          efficiency[!is.finite(perf)] <- NA_real_
        } else if (min_perf < max_perf) {
          efficiency <- rep(NA_real_, length(perf))
        } else {
          efficiency <- (min_perf - perf) / (min_perf - max_perf)
          efficiency <- pmax(0, pmin(1, efficiency))  # Bound between 0 and 1
        }
      } else {
        # Higher is better (R², AUC, accuracy, etc.)
        # Efficiency = current_performance / max_performance
        if (max_perf <= 0) {
          efficiency <- rep(NA_real_, length(perf))
        } else {
          efficiency <- perf / max_perf
          efficiency <- pmax(0, pmin(1, efficiency))  # Bound between 0 and 1
        }
      }

      results[[model]][[metric]]$efficiency <- efficiency
    }
  }
  return(results)
}

#' Determine minimum sample sizes that meet efficiency threshold
#'
#' @param results Main results object
#' @param threshold Efficiency threshold (e.g., 0.95)
#' @param metrics Character vector of metric names
#' @return List of minimum sample sizes by model and metric
#' @noRd
determine_minimum_sample_sizes <- function(results, threshold, metrics) {
  validate_threshold(threshold)
  min_sizes <- list()

  for (model in names(results)) {
    min_sizes[[model]] <- list()
    for (metric in metrics) {
      if (!metric %in% names(results[[model]])) next

      eff <- results[[model]][[metric]]$efficiency
      sample_sizes <- results[[model]][[metric]]$sample_size

      # Skip if efficiency not calculated
      if (is.null(eff) || all(is.na(eff))) {
        min_sizes[[model]][[metric]] <- NA
        next
      }

      # Find first sample size where efficiency >= threshold
      qualifying <- sample_sizes[which(eff >= threshold)]
      min_sizes[[model]][[metric]] <- if (length(qualifying)) min(qualifying) else NA_real_
    }
  }

  return(min_sizes)
}

#' Generate summary plots
#'
#' @param results Main results object
#' @param min_sample_sizes List of minimum sample sizes
#' @return List of plot objects (base R or ggplot2 if available)
#' @noRd
generate_summary_plots <- function(results, min_sample_sizes) {
  plots <- list()
  sample_size <- q025 <- q975 <- NULL

  # Check if ggplot2 is available
  use_ggplot <- requireNamespace("ggplot2", quietly = TRUE)

  for (model in names(results)) {
    for (metric in names(results[[model]])) {
      plot_data <- results[[model]][[metric]]

      if (use_ggplot) {
        # Create ggplot2 plot
        p <- ggplot2::ggplot(plot_data, ggplot2::aes(x = sample_size, y = mean)) +
          ggplot2::geom_line(color = "blue", linewidth = 1) +
          ggplot2::geom_ribbon(ggplot2::aes(ymin = q025, ymax = q975), alpha = 0.2) +
          ggplot2::labs(
            title = paste(model, "-", metric),
            x = "Sample Size",
            y = metric
          ) +
          ggplot2::theme_minimal()

        # Add minimum sample size line if available
        if (!is.null(min_sample_sizes[[model]][[metric]]) &&
            !is.na(min_sample_sizes[[model]][[metric]])) {
          p <- p + ggplot2::geom_vline(
            xintercept = min_sample_sizes[[model]][[metric]],
            linetype = "dashed",
            color = "red"
          )
        }

        plots[[paste(model, metric, sep = "_")]] <- p
      } else {
        # Store data for base R plotting
        plots[[paste(model, metric, sep = "_")]] <- plot_data
      }
    }
  }

  return(plots)
}

#' Plot performance curves
#'
#' @param results Main results object
#' @param model Character string specifying model
#' @param metric Character string specifying metric
#' @param add_efficiency Logical, whether to add efficiency curve
#' @param min_sample_size Numeric, minimum sample size to mark
#' @export
plot_performance_curve <- function(results, model, metric,
                                  add_efficiency = TRUE,
                                  min_sample_size = NULL) {
  if (!model %in% names(results)) {
    stop("Model not found in results: ", model)
  }
  if (!metric %in% names(results[[model]])) {
    stop("Metric not found for model: ", metric)
  }
  old_par <- par(no.readonly = TRUE)
  on.exit(par(old_par), add = TRUE)

  plot_data <- results[[model]][[metric]]

  # Main performance plot
  plot(plot_data$sample_size, plot_data$mean,
       type = "l", lwd = 2, col = "blue",
       xlab = "Sample Size", ylab = metric,
       main = paste(model, "-", metric))

  # Add confidence bands
  polygon(c(plot_data$sample_size, rev(plot_data$sample_size)),
          c(plot_data$q025, rev(plot_data$q975)),
          col = rgb(0, 0, 1, 0.2), border = NA)

  # Add efficiency curve if requested
  if (add_efficiency && "efficiency" %in% names(plot_data)) {
    par(new = TRUE)
    plot(plot_data$sample_size, plot_data$efficiency,
         type = "l", lwd = 2, col = "red", lty = 2,
         axes = FALSE, xlab = "", ylab = "")
    axis(4, col = "red", col.axis = "red")
    mtext("Efficiency", side = 4, line = 3, col = "red")
  }

  # Add minimum sample size marker
  if (!is.null(min_sample_size)) {
    abline(v = min_sample_size, lty = 2, col = "darkgreen", lwd = 2)
    text(min_sample_size, max(plot_data$mean, na.rm = TRUE) * 0.9,
         labels = paste("n =", min_sample_size),
         pos = 4, col = "darkgreen")
  }

  legend("bottomright",
         legend = c("Performance", "95% simulation interval", if(add_efficiency) "Efficiency",
                   if(!is.null(min_sample_size)) "Min n"),
         col = c("blue", rgb(0, 0, 1, 0.2), if(add_efficiency) "red",
                if(!is.null(min_sample_size)) "darkgreen"),
         lwd = c(2, 10, if(add_efficiency) 2, if(!is.null(min_sample_size)) 2),
         lty = c(1, 1, if(add_efficiency) 2, if(!is.null(min_sample_size)) 2))
}

#' Create summary table
#'
#' @param results Main results object
#' @param min_sample_sizes List of minimum sample sizes
#' @return Data frame with summary statistics
#' @noRd
create_summary_table <- function(results, min_sample_sizes) {
  summary_list <- list()

  for (model in names(results)) {
    for (metric in names(results[[model]])) {
      plot_data <- results[[model]][[metric]]

      # Get performance at different sample sizes
      min_n <- plot_data$sample_size[1]
      max_n <- plot_data$sample_size[nrow(plot_data)]
      recommended_n <- min_sample_sizes[[model]][[metric]]

      perf_min <- plot_data$mean[1]
      perf_max <- plot_data$mean[nrow(plot_data)]
      perf_rec <- if (!is.na(recommended_n)) {
        idx <- which(plot_data$sample_size == recommended_n)
        if (length(idx) > 0) plot_data$mean[idx] else NA
      } else NA

      summary_list[[length(summary_list) + 1]] <- data.frame(
        model = model,
        metric = metric,
        min_sample_size = min_n,
        max_sample_size = max_n,
        recommended_sample_size = recommended_n,
        performance_at_min_n = perf_min,
        performance_at_max_n = perf_max,
        performance_at_recommended_n = perf_rec,
        relative_efficiency = if (!is.na(recommended_n) &&
                                  "efficiency" %in% names(plot_data)) {
          plot_data$efficiency[match(recommended_n, plot_data$sample_size)]
        } else NA_real_
      )
    }
  }

  summary_df <- do.call(rbind, summary_list)
  return(summary_df)
}

#' Print simulation summary
#'
#' @param x Output from run_general_simulation.
#' @param ... Further arguments (currently unused).
#' @return The object invisibly.
#' @export
print.sample_size_simulation <- function(x, ...) {
  simulation_result <- x
  cat("Sample Size Simulation Results\n")
  cat("================================\n\n")

  cat("Configuration:\n")
  cat("  Reference Model:", simulation_result$configuration$reference_model, "\n")
  cat("  Target Models:", paste(simulation_result$configuration$target_models, collapse = ", "), "\n")
  cat("  Sample Sizes:", min(simulation_result$configuration$sample_sizes), "to",
      max(simulation_result$configuration$sample_sizes), "\n")
  cat("  Simulations:", simulation_result$configuration$n_simulations, "\n")
  cat("  Metrics:", paste(simulation_result$configuration$metrics, collapse = ", "), "\n\n")

  cat("Minimum Sample Size Recommendations:\n")
  for (model in names(simulation_result$min_sample_sizes)) {
    cat("\n  ", model, ":\n")
    for (metric in names(simulation_result$min_sample_sizes[[model]])) {
      n_min <- simulation_result$min_sample_sizes[[model]][[metric]]
      cat("    ", metric, ":", if(is.na(n_min)) "Not determined" else n_min, "\n")
    }
  }

  invisible(x)
}

#' Summary method for simulation results
#'
#' @param object Output from run_general_simulation.
#' @param ... Further arguments (currently unused).
#' @return Summary table
#' @export
summary.sample_size_simulation <- function(object, ...) {
  create_summary_table(object$results, object$min_sample_sizes)
}
